function investor_num(mixed $value): string { return number_format((float)$value,0,',','.'); }
function investor_delta(int|float $current,int|float $previous): string {
    if ($previous==0) return $current==0?'Sin actividad en ambos períodos':'Actividad nueva; período anterior sin registros';
    $difference=$current-$previous;$percentage=($difference/$previous)*100;
    $sign=$difference>0?'+':($difference<0?'−':'');
    return sprintf('%s%s (%s%%) vs. período anterior',$sign,investor_num(abs($difference)),number_format($percentage,1,',','.'));
}
